// B8 Owner Brief v3-006 — Aggregate stats from 8 sheets (incl. revenue, header-whitespace safe)
const setup = $('Edit Fields — Setup').item.json;
const today = setup['briefDateOnly'];
const yesterday = setup['yesterdayDateOnly'];
const weekStart = setup['weekStartIso'];

const dInRange = (val, start, end) => {
  if (!val) return false;
  const s = String(val).slice(0, 10);
  return s >= start && s <= end;
};
const dStartsWith = (val, prefix) => String(val || '').startsWith(prefix);
const toNum = (v) => { const n = parseFloat(String(v || '0').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const fmtR = (n) => 'R' + Math.round(n).toLocaleString('en-ZA');
const trimKeys = (r) => { const out = {}; for (const [k, v] of Object.entries(r || {})) out[k.trim()] = v; return out; };

let reputation = [], noShow = [], referral = [], recovery = [], reactivation = [], lifetime = [], reviewsEcomm = [], reviewsAirbnb = [];
try { reputation = $('Sheets — Read Reputation').all().map(i => trimKeys(i.json)); } catch(e) {}
try { noShow = $('Sheets — Read No-Show').all().map(i => trimKeys(i.json)); } catch(e) {}
try { referral = $('Sheets — Read Referral').all().map(i => trimKeys(i.json)); } catch(e) {}
try { recovery = $('Sheets — Read Recovery').all().map(i => trimKeys(i.json)); } catch(e) {}
try { reactivation = $('Sheets — Read Reactivation Log').all().map(i => trimKeys(i.json)); } catch(e) {}
try { lifetime = $('Sheets — Read Lifetime').all().map(i => trimKeys(i.json)); } catch(e) {}
try { reviewsEcomm = $('Sheets — Read Reviews EComm').all().map(i => trimKeys(i.json)); } catch(e) {}
try { reviewsAirbnb = $('Sheets — Read Reviews Airbnb').all().map(i => trimKeys(i.json)); } catch(e) {}

// Reputation stats (B6) — unchanged
const repToday = reputation.filter(r => dStartsWith(r['Triggered At'], today));
const repUnhappy = reputation.filter(r => { const rating = parseInt(r['Rating']); return rating > 0 && rating < 4; });
const repPendingFollowup = repUnhappy.filter(r => r['Status'] !== 'Resolved' && r['Owner Alerted'] === 'Yes');
const repPublicReviews = reputation.filter(r => r['Public Review Sent'] === 'Yes');

// No-Show stats (B3) — unchanged
const nsToday = noShow.filter(n => dStartsWith(n['Created At'], today));
const nsNoShowsAll = noShow.filter(n => n['No-Show'] === 'Yes');
const nsRescued = noShow.filter(n => n['Rescue Sent'] === 'Yes');
const nsNeedsCall = nsNoShowsAll.filter(n => (!n['Rebooked'] || n['Rebooked'] === 'No'));

// Referral stats (B7) — unchanged
const refConverted = referral.filter(r => r['Status'] === 'Converted' || r['Converted At']);
const refPending = referral.filter(r => r['Status'] === 'Asked' && !r['Converted At']);
const refRecentConverts = refConverted.filter(r => dStartsWith(r['Converted At'], today) || dStartsWith(r['Converted At'], yesterday));

// Recovery stats (B4) — NEW
const recPaidYesterday = recovery.filter(r => r['Status'] === 'Paid' && dStartsWith(r['Date Paid'], yesterday));
const recPaidWeek = recovery.filter(r => r['Status'] === 'Paid' && dInRange(r['Date Paid'], weekStart, today));
const recOpen = recovery.filter(r => r['Status'] === 'Active' || r['Status'] === 'In Progress');
const recOpenStage3 = recOpen.filter(r => String(r['Stage'] || '').includes('3'));
const revenueRecoveredYesterday = recPaidYesterday.reduce((s, r) => s + toNum(r['Amount Recovered']), 0);
const revenueRecoveredWeek = recPaidWeek.reduce((s, r) => s + toNum(r['Amount Recovered']), 0);
const invoicesOpenSum = recOpen.reduce((s, r) => s + toNum(r['Invoice Amount']), 0);

// Reactivation stats (B5) — NEW
const reactSentYesterday = reactivation.filter(r => dStartsWith(r['Sent At'], yesterday));
const reactSentWeek = reactivation.filter(r => dInRange(r['Sent At'], weekStart, today));
const reactRecovered = reactivation.filter(r => r['Recovered'] === 'Yes');
const reactRecoveredYesterday = reactRecovered.filter(r => dStartsWith(r['Sent At'], yesterday));

// Lifetime stats (B10) — NEW
const lifetimeUpdatedYesterday = lifetime.filter(l => dStartsWith(l['Last Updated'], yesterday));
const totalCustomers = lifetime.length;
const totalLifetimeSpend = lifetime.reduce((s, l) => s + toNum(l['Total Spend']), 0);
const avgOrderAcrossCustomers = lifetime.length > 0 ? lifetime.reduce((s, l) => s + toNum(l['Average Order Value']), 0) / lifetime.length : 0;
const tierUpgradesYesterday = lifetimeUpdatedYesterday.filter(l => l['Previous Tier'] && l['Tier'] && l['Tier'] !== l['Previous Tier']);
const purchaseRevenueYesterday = Math.round(lifetimeUpdatedYesterday.length * avgOrderAcrossCustomers);

// Review stats (B11) — NEW · merge E-Comm + Airbnb (different column names)
const reviewsNormalised = [
  ...reviewsEcomm.map(r => ({ ts: r['Timestamp'], rating: parseInt(r['Star Rating']) || 0, source: 'ecomm' })),
  ...reviewsAirbnb.map(r => ({ ts: r['Timestamp'], rating: parseInt(r['Rating']) || 0, source: 'airbnb' }))
];
const reviewsYesterday = reviewsNormalised.filter(r => dStartsWith(r.ts, yesterday));
const reviewsWeek = reviewsNormalised.filter(r => dInRange(r.ts, weekStart, today));
const reviewsRated = reviewsYesterday.filter(r => r.rating > 0);
const avgRatingYesterday = reviewsRated.length > 0 ? (reviewsRated.reduce((s, r) => s + r.rating, 0) / reviewsRated.length).toFixed(1) : '—';
const negativeFlaggedYesterday = reviewsRated.filter(r => r.rating <= 3);

// Combined revenue (the headline number)
const totalRevenueYesterday = revenueRecoveredYesterday + purchaseRevenueYesterday;
const eventsYesterday = recPaidYesterday.length + reviewsYesterday.length + reactRecoveredYesterday.length + lifetimeUpdatedYesterday.length;

// Action items (top 3 each, most urgent)
const unhappyToCall = repPendingFollowup.slice(0, 3).map(r => ({
  name: r['Customer Name'] || 'Unknown',
  email: r['Customer Email'] || '',
  rating: r['Rating'] || '?',
  product: r['Product Service'] || ''
}));
const noShowsToFollow = nsNeedsCall.slice(0, 3).map(n => ({
  name: n['Customer Name'] || 'Unknown',
  email: n['Customer Email'] || '',
  service: n['Service'] || '',
  apt: n['Appointment Time'] || ''
}));
const conversionsToThank = refRecentConverts.slice(0, 3).map(r => ({
  advocate: r['Advocate Name'] || 'Unknown',
  friend: r['Friend Name'] || '',
  reward: r['Advocate Reward'] || ''
}));
const stage3Invoices = recOpenStage3.slice(0, 3).map(r => ({
  debtor: r['Debtor Name'] || 'Unknown',
  amount: toNum(r['Invoice Amount']),
  days: r['Days Overdue'] || '?',
  invoice: r['Invoice Number'] || ''
}));

const totalActions = unhappyToCall.length + noShowsToFollow.length + conversionsToThank.length + stage3Invoices.length;

return [{
  json: {
    ...setup,
    stats: {
      // Reputation
      repTodaysChecks: repToday.length,
      repTotalChecks: reputation.length,
      repUnhappyCount: repUnhappy.length,
      repPendingFollowup: repPendingFollowup.length,
      repPublicReviews: repPublicReviews.length,
      // No-Show
      nsTodaysBookings: nsToday.length,
      nsTotalBookings: noShow.length,
      nsNoShowsCount: nsNoShowsAll.length,
      nsRescuedCount: nsRescued.length,
      nsNeedsCall: nsNeedsCall.length,
      // Referral
      refTotal: referral.length,
      refConverted: refConverted.length,
      refPending: refPending.length,
      refRecentConverts: refRecentConverts.length,
      // Recovery (NEW)
      revenueRecoveredYesterday: Math.round(revenueRecoveredYesterday),
      revenueRecoveredYesterdayFmt: fmtR(revenueRecoveredYesterday),
      revenueRecoveredWeek: Math.round(revenueRecoveredWeek),
      revenueRecoveredWeekFmt: fmtR(revenueRecoveredWeek),
      invoicesPaidYesterday: recPaidYesterday.length,
      invoicesPaidWeek: recPaidWeek.length,
      invoicesOpenCount: recOpen.length,
      invoicesOpenSumFmt: fmtR(invoicesOpenSum),
      invoicesStage3: recOpenStage3.length,
      // Reactivation (NEW)
      reactivationsSentYesterday: reactSentYesterday.length,
      reactivationsSentWeek: reactSentWeek.length,
      reactivationsRecoveredYesterday: reactRecoveredYesterday.length,
      reactivationsRecoveredTotal: reactRecovered.length,
      // Lifetime (NEW)
      purchasesLoggedYesterday: lifetimeUpdatedYesterday.length,
      purchaseRevenueYesterdayFmt: fmtR(purchaseRevenueYesterday),
      totalCustomers,
      totalLifetimeSpendFmt: fmtR(totalLifetimeSpend),
      tierUpgradesYesterday: tierUpgradesYesterday.length,
      // Reviews (NEW)
      reviewsRepliedYesterday: reviewsYesterday.length,
      reviewsRepliedWeek: reviewsWeek.length,
      avgRatingYesterday,
      negativeReviewsYesterday: negativeFlaggedYesterday.length,
      // Combined headline
      totalRevenueYesterday: Math.round(totalRevenueYesterday),
      totalRevenueYesterdayFmt: fmtR(totalRevenueYesterday),
      eventsYesterday,
      // Meta
      totalActions
    },
    actions: {
      unhappyToCall,
      noShowsToFollow,
      conversionsToThank,
      stage3Invoices
    }
  }
}];

