const promptVersion = 'b8-brief-v1';
// B8 Owner Brief v3-002 — Parse AI insight
const rawText = $input.item.json['rawAIText'] || '';
const d = $('Code — Aggregate Stats').item.json;

const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}
if (!parsed || !parsed['todaysFocus']) {
  let fallbackFocus;
  if (d.stats.repPendingFollowup > 0) {
    fallbackFocus = 'Call the ' + d.stats.repPendingFollowup + ' unhappy customer(s) waiting for follow-up before they post publicly.';
  } else if (d.stats.invoicesStage3 > 0) {
    fallbackFocus = 'Phone ' + d.stats.invoicesStage3 + ' Stage 3 invoice debtor(s) today — bot has done all it can.';
  } else if (d.stats.nsNeedsCall > 0) {
    fallbackFocus = 'Follow up with ' + d.stats.nsNeedsCall + ' no-show(s) by phone today — best chance to rebook.';
  } else if (d.stats.revenueRecoveredYesterday > 0) {
    fallbackFocus = 'You recovered ' + d.stats.revenueRecoveredYesterdayFmt + ' yesterday — keep momentum on the open ' + d.stats.invoicesOpenSumFmt + '.';
  } else {
    fallbackFocus = 'Quiet morning — review the activity below and pick one customer to send a personal note to.';
  }
  parsed = {
    headline: 'Daily Owner Brief',
    todaysFocus: fallbackFocus,
    insight: 'Brief generated from ' + d.stats.repTotalChecks + ' rep checks, ' + d.stats.nsTotalBookings + ' bookings, ' + d.stats.totalCustomers + ' customers.'
  };
}
const parseSuccess = !!parsed['todaysFocus'] && parsed['headline'] !== 'Daily Owner Brief';
return { ...d, promptVersion, headline: parsed['headline'], todaysFocus: parsed['todaysFocus'], insight: parsed['insight'], parseSuccess };

